package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64 // tokens per second
	burst    float64
	clock    Clock
}

var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be positive")

// New returns a Limiter with a full bucket. rate > 0 and burst > 0 are required.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is New with an injectable clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, ErrInvalidConfig
	}
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	return &Limiter{
		tokens: float64(burst),
		last:   clock.Now(),
		rate:   rate,
		burst:  float64(burst),
		clock:  clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at time now, consuming them if so.
func (l *Limiter) AllowN(n int) bool {
	return l.AllowNAt(l.clock.Now(), n)
}

// AllowNAt is AllowN at an explicit time; useful for tests and batching.
func (l *Limiter) AllowNAt(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	if now.Before(l.last) {
		now = l.last // guard against clock going backwards
	}
	elapsed := now.Sub(l.last).Seconds()
	l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
	l.last = now

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (fractional).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
