// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu       sync.Mutex
	rate     float64 // tokens per second
	burst    float64 // bucket capacity
	tokens   float64
	lastTime time.Time
	clock    Clock
}

var (
	ErrRate  = errors.New("ratelimit: rate must be > 0")
	ErrBurst = errors.New("ratelimit: burst must be > 0")
)

// New returns a Limiter with a full bucket, using the real clock.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock returns a Limiter with a full bucket and an injectable clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrRate
	}
	if burst <= 0 {
		return nil, ErrBurst
	}
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	return &Limiter{
		rate:     rate,
		burst:    float64(burst),
		tokens:   float64(burst),
		lastTime: clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.lastTime).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.lastTime = now
	}

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// RetryAfter returns the duration until n tokens would be available,
// or 0 if they are available now. n must be >= 0.
func (l *Limiter) RetryAfter(n int) time.Duration {
	if n < 0 {
		return -1
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	need := float64(n) - l.tokens
	if need <= 0 {
		return 0
	}
	return time.Duration(need / l.rate * float64(time.Second))
}
