// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by time.Now.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64 // tokens per second
	burst    float64
	clock    Clock
	maxDelay time.Duration
}

var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be positive")

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// capacity. The bucket starts full.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, RealClock())
}

// NewWithClock is New with an injectable Clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	now := clock.Now()
	return &Limiter{
		tokens: float64(burst),
		last:   now,
		rate:   rate,
		burst:  float64(burst),
		clock:  clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	return l.reserve(now, n) >= 0
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// reserve advances the bucket to now and consumes n tokens.
// Returns the wait time for the request to be satisfiable, or -1 if it
// exceeds maxDelay (i.e., never satisfiable within policy).
func (l *Limiter) reserve(now time.Time, n int) time.Duration {
	if n < 0 {
		return -1
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	if now.Before(l.last) {
		now = l.last // guard against clock going backwards
	}
	elapsed := now.Sub(l.last).Seconds()
	l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
	l.last = now

	need := float64(n)
	if need <= l.tokens {
		l.tokens -= need
		return 0
	}
	// Time until enough tokens accumulate.
	wait := time.Duration((need - l.tokens) / l.rate * float64(time.Second))
	if wait > l.maxDelay {
		return -1
	}
	// Commit the future consumption.
	l.tokens = 0
	l.last = now.Add(wait)
	return wait
}

// WaitN blocks until n tokens can be consumed, or returns an error if the
// required delay exceeds the limiter's policy or the context is done.
func (l *Limiter) WaitN(n int) error {
	now := l.clock.Now()
	d := l.reserve(now, n)
	if d < 0 {
		return errors.New("ratelimit: request exceeds allowed delay")
	}
	if d > 0 {
		time.Sleep(d)
	}
	return nil
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
