// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time so tests can inject a fake.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a token-bucket rate limiter. Tokens refill continuously at
// rate tokens per second, up to the bucket capacity. The zero value is not
// usable; construct with New.
type Limiter struct {
	mu       sync.Mutex
	clock    Clock
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
}

// ErrInvalidConfig is returned by New for non-positive capacity or rate.
var ErrInvalidConfig = errors.New("ratelimit: capacity and rate must be > 0")

// New returns a Limiter with a full bucket. capacity is the maximum burst
// size; rate is the steady-state refill rate in tokens per second.
func New(capacity, rate float64) (*Limiter, error) {
	return NewWithClock(capacity, rate, realClock{})
}

// NewWithClock is New with an injectable Clock.
func NewWithClock(capacity, rate float64, c Clock) (*Limiter, error) {
	if c == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if capacity <= 0 {
		return nil, fmt.Errorf("%w: capacity %v", ErrInvalidConfig, capacity)
	}
	if rate <= 0 {
		return nil, fmt.Errorf("%w: rate %v", ErrInvalidConfig, rate)
	}
	return &Limiter{
		clock:    c,
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     c.Now(),
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at the current time,
// consuming them if so. It is safe for concurrent use.
func (l *Limiter) AllowN(n float64) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.capacity, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if n <= l.tokens {
		l.tokens -= n
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (mainly for tests).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := l.clock.Now().Sub(l.last).Seconds()
	if elapsed > 0 {
		return min(l.capacity, l.tokens+elapsed*l.rate)
	}
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
