// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock reports the current time. It is an abstraction over time.Now to
// allow deterministic testing.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the system time.
func RealClock() Clock { return realClock{} }

// ErrInvalidConfig is returned by New when its arguments are invalid.
var ErrInvalidConfig = errors.New("ratelimit: invalid configuration")

// Limiter is a concurrency-safe token-bucket rate limiter.
//
// The bucket holds at most Burst tokens and is refilled at Rate tokens per
// second. A zero Rate disables refilling entirely (the bucket drains and
// never recovers).
type Limiter struct {
	mu     sync.Mutex
	tokens float64
	last   time.Time

	rate float64 // tokens per second
	burst float64
	clock Clock
}

// New returns a Limiter with the given refill rate (tokens per second) and
// burst capacity, starting full. rate must be > 0 and burst must be > 0.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, RealClock())
}

// NewWithClock is like New but uses the supplied Clock. It is primarily
// intended for testing.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, ErrInvalidConfig
	}
	if math.IsNaN(rate) || rate <= 0 || math.IsInf(rate, 0) {
		return nil, ErrInvalidConfig
	}
	if burst <= 0 {
		return nil, ErrInvalidConfig
	}
	return &Limiter{
		tokens: float64(burst),
		burst:  float64(burst),
		rate:   rate,
		clock:  clock,
		last:   clock.Now(),
	}, nil
}

// Allow reports whether a single token may be consumed.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens may be consumed at the current instant.
// If the bucket contains fewer than n tokens, no tokens are consumed and
// false is returned; consumption is all-or-nothing.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	l.advance(now)
	if l.tokens < float64(n) {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Tokens returns the current number of available tokens, advanced to the
// present instant. It is primarily for observability and testing.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	return l.tokens
}

// advance refills tokens based on elapsed time since the last update.
// Caller must hold l.mu.
func (l *Limiter) advance(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.last = now
	l.tokens = math.Min(l.burst, l.tokens+elapsed*l.rate)
}
